    constructor(C _c) { c = _c; }

    // Drive contract and check invariant: zero-value Put must not change stored balance
    function check_zero_put_does_not_change_balance(uint unlockTime, uint sendAmt) public {
        // prepare: this test only meaningful when caller has enough balance to send sendAmt (if used)
        require(sendAmt == 0, "sendAmt must be zero for this invariant test");

        // observe balance before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // perform zero-value Put via fallback or direct call; use direct call with zero value
        c.Put{value: 0}(unlockTime);

        // observe after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // The invariant: balance must be unchanged when sending zero value
        assert(afterBalance == beforeBalance);
    }

    // allow contract to receive ETH if needed elsewhere
    receive() external payable {}
}

