// Minimal interface helper to access Log from C via its public getters
contract Log {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;

    // small helper getters matching the internal structure to allow reads from the test
    function HistoryLength() external view returns (uint256) { return History.length; }
    function HistorySender(uint256 i) external view returns (address) { return History[i].Sender; }
}

