        vm.assume(actor != address(0));
        // zero-value call is the distinguishing case; fuzz _unlockTime widely
        // fund the actor so they can make calls (even though value is zero)
        vm.deal(actor, 1 ether);

        // record current block timestamp
        uint ts = block.timestamp;

        // perform a zero-value Put from actor
        vm.prank(actor);
        // call with zero value
        c.Put{value: 0}(_unlockTime);

        // The reference contract always updates Acc[actor].unlockTime to at least block.timestamp
        // even when msg.value == 0. The mutant that returns early on msg.value==0 will not.
        // Read the public getter for Acc (mapping to struct) -> generated getter returns (uint,uint)
        (uint gotUnlock,,) = _readAcc(actor);

        // Assert the universal property: recorded unlockTime is >= the timestamp at call time
        assertTrue(gotUnlock >= ts);
    }

    // helper to decode the public getter return of Acc (mapping to struct Holder)
    // Since the mapping getter for a struct returns a tuple (unlockTime, balance),
    // but different compiler versions may vary, we route through a try/catch on the auto getter.
    function _readAcc(address a) internal returns (uint unlockTime, uint balance, bool ok) {
        // The auto-generated getter signature is: function Acc(address) public view returns (uint,uint);
        // Use low-level staticcall to be robust and decode accordingly.
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", a));
        if (!success || data.length < 64) {
            // if call fails or unexpected shape, return zeros but mark ok=false
            return (0,0,false);
        }
        uint _u = abi.decode(data, (uint, uint))[0];
        uint _b = abi.decode(data, (uint, uint))[1];
        return (_u, _b, true);
    }
}

