        require(sent, "funding attacker failed");

        // set c's minimum sum low so deposit qualifies
        // cannot directly change c.MinSum; instead ensure dep >= MinSum by choosing bounds; MinSum is 1 ether in contract
        vm.assume(dep >= 1 ether);

        // warp forward so unlock time condition satisfied
        vm.warp(block.timestamp + 100);

        // Record balance in c for attacker before Collect
        uint256 before = c.Acc(address(attacker)).balance;

